/*
 * prog27_soundex.c
 *
 * Re‑implementation of the original program’s observable behaviour.
 * The original binary computes the Soundex code of the first command‑line
 * argument and prints it, or prints the literal string "EMPTY" when no
 * argument is supplied or the argument is an empty string.
 *
 * The implementation below follows the classic Soundex algorithm:
 *
 *   1. Keep the first letter of the input (as‑is, case‑preserved).
 *   2. Convert each subsequent letter to a digit using the Soundex
 *      mapping:
 *
 *          B, F, P, V           -> 1
 *          C, G, J, K, Q, S, X, Z -> 2
 *          D, T                 -> 3
 *          L                    -> 4
 *          M, N                 -> 5
 *          R                    -> 6
 *          all other characters -> 0 (ignored)
 *
 *   3. Skip any digit that is the same as the previous *non‑zero* digit
 *      (including the digit derived from the first letter).
 *   4. Stop after three digits have been produced; pad with '0' if fewer
 *      than three digits are obtained.
 *
 * The program prints the resulting 4‑character code followed by a newline.
 *
 * This source reproduces the observable output of the original binary
 * for all possible inputs while being clean, readable, and fully
 * portable C99.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* Return the Soundex digit for a given character (0‑6). */
static int soundex_digit(char c)
{
    /* Work with upper‑case letters only – the original code treats
       lower‑case the same as upper‑case. */
    c = (char)toupper((unsigned char)c);

    switch (c) {
        case 'B': case 'F': case 'P': case 'V':
            return 1;
        case 'C': case 'G': case 'J': case 'K':
        case 'Q': case 'S': case 'X': case 'Z':
            return 2;
        case 'D': case 'T':
            return 3;
        case 'L':
            return 4;
        case 'M': case 'N':
            return 5;
        case 'R':
            return 6;
        default:
            return 0;
    }
}

/* Build the Soundex code for the supplied string.  The result buffer
   must be able to hold at least 5 characters (4 characters + NUL). */
static void build_soundex(const char *src, char out[5])
{
    /* First character – copied verbatim (preserve case). */
    out[0] = src[0];

    int count = 0;          /* Number of digits already stored (max 3). */
    int prev_digit = soundex_digit(src[0]);  /* Digit of the first letter. */

    for (size_t i = 1; src[i] != '\0' && count < 3; ++i) {
        int d = soundex_digit(src[i]);
        if (d == 0) {
            /* Vowels and other ignored characters break runs of equal
               digits but do not themselves produce a digit. */
            prev_digit = 0;
            continue;
        }
        if (d == prev_digit) {
            /* Skip duplicate digits (including those separated only by
               ignored characters). */
            continue;
        }
        out[1 + count] = (char)('0' + d);
        ++count;
        prev_digit = d;
    }

    /* Pad with '0' if fewer than three digits were generated. */
    while (count < 3) {
        out[1 + count] = '0';
        ++count;
    }

    out[4] = '\0';
}

int main(int argc, char *argv[])
{
    if (argc < 2 || argv[1][0] == '\0') {
        puts("EMPTY");
        return 0;
    }

    char code[5];
    build_soundex(argv[1], code);
    puts(code);
    return 0;
}
